using System.Diagnostics;
using System.Runtime.InteropServices;

namespace BluetoothGamepadBridge;

/// <summary>
/// Intercepts and swallows synthetic keystrokes injected into Windows OS by background
/// mappers such as Steam's "Desktop Layout" or Windows Game Bar navigation.
/// 
/// Crucially: Physical keyboard and mouse events generated by human hands are NOT injected,
/// so they pass through completely untouched, allowing normal PC usage.
/// </summary>
public static class InputInterceptor
{
    private const int WH_KEYBOARD_LL = 13;
    private const int WM_KEYDOWN = 0x0100;
    private const int WM_KEYUP = 0x0101;
    private const int WM_SYSKEYDOWN = 0x0104;
    private const int WM_SYSKEYUP = 0x0105;

    // Injected flags in KBDLLHOOKSTRUCT
    private const uint LLKHF_INJECTED = 0x00000001;
    private const uint LLKHF_LOWER_IL_INJECTED = 0x00000002;

    [StructLayout(LayoutKind.Sequential)]
    private struct KBDLLHOOKSTRUCT
    {
        public uint vkCode;
        public uint scanCode;
        public uint flags;
        public uint time;
        public UIntPtr dwExtraInfo;
    }

    private delegate IntPtr LowLevelKeyboardProc(int nCode, IntPtr wParam, IntPtr lParam);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr SetWindowsHookEx(int idHook, LowLevelKeyboardProc lpfn, IntPtr hMod, uint dwThreadId);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool UnhookWindowsHookEx(IntPtr hhk);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr CallNextHookEx(IntPtr hhk, int nCode, IntPtr wParam, IntPtr lParam);

    [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr GetModuleHandle(string? lpModuleName);

    private static IntPtr _hookId = IntPtr.Zero;
    private static LowLevelKeyboardProc? _proc;
    public static bool IsEnabled { get; private set; }

    // Track intercepted events count
    public static long InterceptedKeysCount { get; private set; }

    public static void Enable()
    {
        if (IsEnabled) return;

        try
        {
            _proc = HookCallback;
            using var curProcess = Process.GetCurrentProcess();
            using var curModule = curProcess.MainModule;
            IntPtr moduleHandle = GetModuleHandle(curModule?.ModuleName);
            _hookId = SetWindowsHookEx(WH_KEYBOARD_LL, _proc, moduleHandle, 0);
            IsEnabled = (_hookId != IntPtr.Zero);
        }
        catch
        {
            IsEnabled = false;
        }
    }

    public static void Disable()
    {
        if (!IsEnabled) return;
        if (_hookId != IntPtr.Zero)
        {
            UnhookWindowsHookEx(_hookId);
            _hookId = IntPtr.Zero;
        }
        _proc = null;
        IsEnabled = false;
    }

    private static IntPtr HookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode >= 0)
        {
            var hookStruct = Marshal.PtrToStructure<KBDLLHOOKSTRUCT>(lParam);

            // Check if this keystroke was injected by software (Steam Desktop Layout, Game Bar, etc.)
            bool isInjected = (hookStruct.flags & LLKHF_INJECTED) != 0 ||
                              (hookStruct.flags & LLKHF_LOWER_IL_INJECTED) != 0;

            if (isInjected)
            {
                // Common keys generated by controller-to-desktop mappers:
                // Enter, Space, Backspace, Escape, Tab, Arrow keys, Win key
                uint vk = hookStruct.vkCode;
                bool isControllerDesktopKey = (vk >= 0x25 && vk <= 0x28) // Left, Up, Right, Down arrows
                                           || vk == 0x0D // Enter (mapped to A)
                                           || vk == 0x1B // Escape (mapped to B)
                                           || vk == 0x08 // Backspace (mapped to B)
                                           || vk == 0x20 // Space (mapped to X)
                                           || vk == 0x09 // Tab (mapped to Y)
                                           || vk == 0x5B // Left Windows Key (Guide)
                                           || vk == 0x5C; // Right Windows Key

                if (isControllerDesktopKey)
                {
                    InterceptedKeysCount++;
                    // Return 1 to swallow the event so Windows OS and terminal never see it!
                    return (IntPtr)1;
                }
            }
        }

        return CallNextHookEx(_hookId, nCode, wParam, lParam);
    }
}

